"use client";

import { motion } from "framer-motion";
import { 
  Users, Mail, CheckCircle, Wallet, PenTool, FilePlus, 
  ClipboardList, MessageCircle, UserCheck, Settings, Bell, 
  TrendingUp, Activity, ArrowRight, MoreHorizontal 
} from "lucide-react";
import { ActivityChart, ProkerChart } from "@/components/DashboardCharts"; 

const formatCurrency = (amount: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency',
    currency: 'IDR',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);
};

// === STAT CARD (UPGRADED LIGHT MODE) ===
const StatCard = ({ title, value, icon: Icon, color, delay }: any) => (
  <motion.div 
    initial={{ opacity: 0, y: 20 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ delay }}
    className="relative group p-6 rounded-[2rem] bg-white/80 dark:bg-[#0f172a]/60 backdrop-blur-xl border border-white/20 dark:border-white/5 hover:border-blue-500/50 dark:hover:border-slate-500 transition-all overflow-hidden shadow-sm hover:shadow-xl dark:shadow-2xl"
  >
    {/* Background Gradient Halus di Light Mode */}
    <div className={`absolute inset-0 bg-gradient-to-br from-${color}-50/50 to-transparent dark:from-transparent opacity-100 dark:opacity-0`} />

    <div className={`absolute -right-4 -bottom-4 opacity-10 group-hover:opacity-20 transition-opacity text-${color}-500 transform rotate-12`}>
       <Icon size={100} strokeWidth={1} />
    </div>
    
    <div className="relative z-10">
      <div className={`w-12 h-12 rounded-2xl bg-${color}-100 dark:bg-${color}-500/20 flex items-center justify-center text-${color}-600 dark:text-${color}-400 mb-4 shadow-sm`}>
        <Icon size={24} />
      </div>
      <h3 className="text-slate-500 dark:text-slate-400 text-xs font-bold uppercase tracking-widest mb-1">{title}</h3>
      <p className="text-3xl font-black text-slate-900 dark:text-white tracking-tight">{value}</p>
    </div>
  </motion.div>
);

export default function AdminDashboard() {
  return (
    <div className="space-y-8 relative">
      
      {/* === BACKGROUND DECORATION (LIGHT MODE FIX) === */}
      {/* Ini biar Light Mode ga putih polos, tapi ada 'Ambience' */}
      <div className="fixed inset-0 pointer-events-none -z-10 bg-slate-50 dark:bg-transparent transition-colors duration-500" />
      <div className="absolute top-0 left-0 w-full h-[500px] bg-gradient-to-b from-blue-100/40 via-purple-100/20 to-transparent dark:opacity-0 pointer-events-none -z-10 blur-3xl" />

      {/* === HEADER === */}
      <div className="flex flex-col-reverse md:flex-row justify-between items-start md:items-center gap-6 pb-2">
         <div>
            <h1 className="text-3xl md:text-4xl font-black mb-2 text-slate-900 dark:text-white tracking-tight">
              Command Center <span className="text-blue-600">v2.0</span>
            </h1>
            <p className="text-slate-500 dark:text-slate-400 font-medium">
              Ringkasan aktivitas sistem hari ini, Kapten.
            </p>
         </div>

         {/* PROFIL WIDGET (Lebih Rapi) */}
         <div className="flex items-center gap-4 bg-white/60 dark:bg-white/5 p-1.5 pr-6 rounded-full border border-white/40 dark:border-white/10 shadow-sm backdrop-blur-md">
            <div className="relative">
               <div className="w-10 h-10 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 p-[2px]">
                  <div className="w-full h-full rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center overflow-hidden">
                     <span className="text-lg">😎</span> 
                  </div>
               </div>
               <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 border-2 border-white dark:border-[#0f172a] rounded-full" />
            </div>
            <div className="hidden md:block text-left">
               <h4 className="text-xs font-bold text-slate-800 dark:text-white leading-none">Raka Aditya</h4>
               <span className="text-[10px] font-bold text-blue-500 dark:text-blue-400">Ketua OSIS</span>
            </div>
            <div className="w-[1px] h-6 bg-slate-200 dark:bg-white/10 mx-2" />
            <button className="relative text-slate-500 hover:text-blue-600 dark:text-slate-400 dark:hover:text-white transition-colors">
               <Bell size={20} />
               <span className="absolute top-0 right-0 w-2 h-2 bg-red-500 rounded-full border border-white dark:border-[#0f172a]" />
            </button>
         </div>
      </div>

      {/* === STATS GRID === */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
         <StatCard title="Total Siswa" value="1,240" icon={Users} color="blue" delay={0.1} />
         <StatCard title="Aspirasi Baru" value="18" icon={Mail} color="purple" delay={0.2} />
         <StatCard title="Proker Selesai" value="85%" icon={CheckCircle} color="green" delay={0.3} />
         <StatCard title="Dana Kas" value={formatCurrency(12500000)} icon={Wallet} color="yellow" delay={0.4} />
      </div>

      {/* === BENTO GRID LAYOUT (The Professional Look) === */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
         
         {/* ITEM 1: Activity Chart (Large) */}
         <motion.div 
            initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.5 }}
            className="lg:col-span-2 bg-white/60 dark:bg-[#0f172a]/60 backdrop-blur-xl border border-white/40 dark:border-white/10 rounded-[2rem] p-8 shadow-sm"
         >
            <div className="flex items-center justify-between mb-6">
               <div className="flex items-center gap-3">
                  <div className="p-2 bg-blue-100 dark:bg-blue-900/20 rounded-xl text-blue-600 dark:text-blue-400">
                    <Activity size={20} />
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-900 dark:text-white">Tren Aktivitas</h3>
                    <p className="text-xs text-slate-500 dark:text-slate-400">Statistik minggu ini</p>
                  </div>
               </div>
            </div>
            <ActivityChart />
         </motion.div>

         {/* ITEM 2: Quick Actions (Compact Grid) */}
         <motion.div 
           initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.6 }}
           className="bg-white/60 dark:bg-[#0f172a]/60 backdrop-blur-xl border border-white/40 dark:border-white/10 rounded-[2rem] p-8 shadow-sm flex flex-col"
         >
            <div className="flex items-center gap-3 mb-6">
                <div className="p-2 bg-purple-100 dark:bg-purple-900/20 rounded-xl text-purple-600 dark:text-purple-400">
                  <PenTool size={20} />
                </div>
                <h3 className="font-bold text-slate-900 dark:text-white">Akses Cepat</h3>
            </div>
            
            <div className="grid grid-cols-2 gap-3 flex-1">
               {[
                 { label: 'Tulis Berita', icon: PenTool, color: 'blue' },
                 { label: 'Buat Proker', icon: FilePlus, color: 'green' },
                 { label: 'Cek Laporan', icon: ClipboardList, color: 'orange' },
                 { label: 'Broadcast', icon: MessageCircle, color: 'pink' },
               ].map((item, i) => (
                  <button key={i} className="flex flex-col items-center justify-center gap-2 p-4 rounded-2xl bg-white dark:bg-white/5 border border-slate-100 dark:border-white/5 hover:border-blue-500/50 hover:bg-blue-50/50 dark:hover:bg-blue-900/20 transition-all group">
                     <item.icon size={24} className={`text-${item.color}-500 group-hover:scale-110 transition-transform`} />
                     <span className="text-xs font-bold text-slate-600 dark:text-slate-300">{item.label}</span>
                  </button>
               ))}
            </div>
         </motion.div>

         {/* ITEM 3: Proker Chart */}
         <motion.div 
            initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.7 }}
            className="bg-white/60 dark:bg-[#0f172a]/60 backdrop-blur-xl border border-white/40 dark:border-white/10 rounded-[2rem] p-8 shadow-sm"
         >
            <div className="flex items-center justify-between mb-4">
               <div className="flex items-center gap-3">
                  <div className="p-2 bg-green-100 dark:bg-green-900/20 rounded-xl text-green-600 dark:text-green-400">
                    <TrendingUp size={20} />
                  </div>
                  <h3 className="font-bold text-slate-900 dark:text-white">Progres Sekbid</h3>
               </div>
            </div>
            <ProkerChart />
         </motion.div>

         {/* ITEM 4: Aspirasi Terbaru (List) */}
         <motion.div 
           initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.8 }}
           className="lg:col-span-2 bg-white/60 dark:bg-[#0f172a]/60 backdrop-blur-xl border border-white/40 dark:border-white/10 rounded-[2rem] p-8 shadow-sm"
         >
            <div className="flex items-center justify-between mb-6">
               <div className="flex items-center gap-3">
                  <div className="p-2 bg-orange-100 dark:bg-orange-900/20 rounded-xl text-orange-600 dark:text-orange-400">
                    <Mail size={20} />
                  </div>
                  <h3 className="font-bold text-slate-900 dark:text-white">Inbox Aspirasi</h3>
               </div>
               <button className="p-2 hover:bg-slate-100 dark:hover:bg-white/10 rounded-full transition-colors">
                  <MoreHorizontal size={20} className="text-slate-400" />
               </button>
            </div>

            <div className="space-y-3">
               {[
                 { name: "Ahmad (X RPL)", msg: "WC di lantai 2 tolong diperbaiki airnya...", time: "2m lalu", tag: "Sarana" },
                 { name: "Siti (XI TKJ)", msg: "Request lagu buat pensi besok dong!", time: "1j lalu", tag: "Event" },
                 { name: "Anonim", msg: "Parkiran motor makin sempit min.", time: "3j lalu", tag: "Umum" },
               ].map((item, i) => (
                 <div key={i} className="group flex items-center justify-between p-4 rounded-2xl bg-white dark:bg-white/5 border border-slate-100 dark:border-white/5 hover:border-blue-500/30 transition-all">
                    <div className="flex items-center gap-4">
                       <div className="w-10 h-10 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center text-sm font-bold text-slate-600 dark:text-slate-300">
                          {item.name.charAt(0)}
                       </div>
                       <div>
                          <h4 className="text-sm font-bold text-slate-900 dark:text-white">{item.name}</h4>
                          <p className="text-xs text-slate-500 dark:text-slate-400 line-clamp-1">{item.msg}</p>
                       </div>
                    </div>
                    <div className="text-right flex flex-col items-end">
                       <span className="text-[10px] font-bold px-2 py-1 rounded-full bg-slate-100 dark:bg-white/10 text-slate-500 dark:text-slate-400 mb-1">
                         {item.tag}
                       </span>
                       <span className="text-[10px] text-slate-400">{item.time}</span>
                    </div>
                 </div>
               ))}
            </div>
            
            <button className="w-full py-4 mt-4 rounded-2xl border border-dashed border-slate-300 dark:border-white/20 text-sm font-bold text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-white/5 hover:text-blue-600 dark:hover:text-blue-400 transition-all flex items-center justify-center gap-2">
               Lihat Semua Pesan <ArrowRight size={16} />
            </button>
         </motion.div>

      </div>
    </div>
  );
}